import{_ as l,C as r,o as d,c,a6 as o,E as i,j as t,a}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"OAuth Authentication","description":"Redirect URI validation, implicit-flow leakage, profile linking, open redirects, proxy pages, and dynamic client registration.","frontmatter":{"title":"OAuth Authentication","description":"Redirect URI validation, implicit-flow leakage, profile linking, open redirects, proxy pages, and dynamic client registration."},"headers":[],"relativePath":"oauth/index.md","filePath":"oauth/index.md"}'),p={name:"oauth/index.md"};function h(u,e,m,g,b,f){const n=r("LabGroup"),s=r("TopicComplete");return d(),c("div",null,[e[0]||(e[0]=o(`<h1 id="oauth-authentication" tabindex="-1">OAuth Authentication <a class="header-anchor" href="#oauth-authentication" aria-label="Permalink to &quot;OAuth Authentication&quot;">​</a></h1><p class="wd-section-lede">OAuth is a delegation protocol, not an authentication protocol. Applications bolt login on top of it and then trust fields the authorization server never verified. The bugs cluster around redirect URIs, state, and account linking.</p><div class="wd-callout"><p><strong>The model.</strong> The client sends the user to the authorization server with a <code>client_id</code>, <code>redirect_uri</code>, <code>scope</code>, and <code>state</code>. The server authenticates the user, obtains consent, and redirects back with a code (or token). The client exchanges the code for an access token and reads a profile. Every parameter in that chain is a trust decision.</p></div><h2 id="the-flow-and-where-it-breaks" tabindex="-1">The flow, and where it breaks <a class="header-anchor" href="#the-flow-and-where-it-breaks" aria-label="Permalink to &quot;The flow, and where it breaks&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>browser → /auth?client_id=...&amp;redirect_uri=...&amp;state=...</span></span>
<span class="line"><span>auth server → user consent → redirect_uri?code=...</span></span>
<span class="line"><span>client → token endpoint → access_token</span></span>
<span class="line"><span>client → /userinfo → {&quot;sub&quot;:&quot;...&quot;,&quot;email&quot;:&quot;...&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><table tabindex="0"><thead><tr><th>Failure</th><th>Consequence</th></tr></thead><tbody><tr><td>redirect URI allow-list too loose</td><td>code/token sent to attacker</td></tr><tr><td><code>state</code> missing or unvalidated</td><td>login CSRF, account linking</td></tr><tr><td>implicit flow token in fragment</td><td>token theft via redirect or proxy</td></tr><tr><td>profile fields trusted</td><td>account takeover by email collision</td></tr><tr><td>dynamic client registration open</td><td>SSRF, client impersonation</td></tr></tbody></table>`,6)),i(n,{ids:"oauth-lab-oauth-authentication-bypass-via-oauth-implicit-flow, oauth-lab-oauth-account-hijacking-via-redirect-uri"}),e[1]||(e[1]=o('<details class="details custom-block"><summary>🔬 Under the Hood: why <code>redirect_uri</code> matching is hard</summary><p>A correct comparison parses both URIs and compares scheme, host, port, and path exactly. Common mistakes:</p><ul><li><strong>Prefix matching:</strong> <code>https://client.example/callback</code> allows <code>https://client.example/callback.evil</code>.</li><li><strong>Substring matching:</strong> allows <code>https://evil.example/?https://client.example</code>.</li><li><strong>Wildcard subdomains:</strong> any compromised subdomain becomes a redirect target.</li><li><strong>Path traversal:</strong> <code>/callback/../evil</code> normalises to <code>/evil</code>.</li><li><strong>Open redirect on the client:</strong> the registered URI redirects again to the attacker.</li></ul><p>The authorization server must not follow redirects, and the client must not have an open redirect at the registered path.</p></details><h2 id="profile-linking-and-state" tabindex="-1">Profile linking and <code>state</code> <a class="header-anchor" href="#profile-linking-and-state" aria-label="Permalink to &quot;Profile linking and `state`&quot;">​</a></h2><p>If the client links an OAuth identity to the current session without a <code>state</code> parameter, an attacker can start the flow, obtain a code for their own account, and trick the victim into completing the link. The victim&#39;s account is then bound to the attacker&#39;s identity.</p>',3)),i(n,{ids:"oauth-lab-oauth-forced-oauth-profile-linking"}),e[2]||(e[2]=t("h2",{id:"token-theft-via-open-redirects-and-proxy-pages",tabindex:"-1"},[a("Token theft via open redirects and proxy pages "),t("a",{class:"header-anchor",href:"#token-theft-via-open-redirects-and-proxy-pages","aria-label":'Permalink to "Token theft via open redirects and proxy pages"'},"​")],-1)),e[3]||(e[3]=t("p",null,[a("Implicit flow returns the access token in the URL fragment. Any script on the redirect target can read it. A proxy page on the client origin that embeds an attacker-controlled URL can leak the fragment through "),t("code",null,"Referer"),a(" or "),t("code",null,"postMessage"),a(".")],-1)),i(n,{ids:"oauth-lab-oauth-stealing-oauth-access-tokens-via-an-open-redirect, oauth-lab-oauth-stealing-oauth-access-tokens-via-a-proxy-page"}),e[4]||(e[4]=t("h2",{id:"dynamic-client-registration",tabindex:"-1"},[a("Dynamic client registration "),t("a",{class:"header-anchor",href:"#dynamic-client-registration","aria-label":'Permalink to "Dynamic client registration"'},"​")],-1)),e[5]||(e[5]=t("p",null,[a("An open registration endpoint lets an attacker create a client with a redirect URI they control, or supply a "),t("code",null,"logo_uri"),a("/"),t("code",null,"jwks_uri"),a(" that the server fetches. The latter is SSRF.")],-1)),i(n,{ids:"oauth-lab-oauth-ssrf-via-openid-dynamic-client-registration"}),e[6]||(e[6]=o('<details class="details custom-block"><summary>⚙️ Engine Variations: provider quirks</summary><ul><li><strong>Google:</strong> requires exact redirect URI matching, but allows <code>http://localhost</code> for native apps.</li><li><strong>GitHub:</strong> path and subpath matching rules differ; query parameters are ignored in some comparisons.</li><li><strong>Azure AD:</strong> supports wildcard redirect URIs for SPA platforms; misconfiguration is common.</li><li><strong>Okta:</strong> per-app grant types and redirect rules; dynamic registration may be enabled.</li><li><strong>Keycloak:</strong> <code>Valid Redirect URIs</code> supports wildcards; <code>+</code> appends valid patterns.</li></ul><p>Read the provider&#39;s matching rules, then test the edge cases it documents.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Use exact redirect URI matching. Require and validate <code>state</code> with a per-session value. Prefer authorization code with PKCE over implicit. Validate the issuer, audience, signature, and expiry of tokens. Do not link accounts by unverified email. Disable dynamic client registration unless required, and validate any URL the server fetches.</p></div>',2)),i(s,{"topic-id":"oauth-authentication",label:"Mark OAuth complete"})])}const _=l(p,[["render",h]]);export{v as __pageData,_ as default};
